#pragma once
#include "bridge_core.h"
#include "actuators.h"
#include "imu.h"

#define ROBOT_ID "diffbot"
#define BRIDGE_BAUD 500000

static const bridge::MotorTuning MOTOR = {660.0f, 0.08f, 0.6f, 0.0f, 20.0f, false, false};   // counts/rev, kp, ki, kd, max rad/s, position mode, invert

static void robot_setup(bridge::Actuator ** a, uint8_t & n, bridge::Imu *& imu)
{
  n = 0;
  static bridge::DcMotor m0(0, {bridge::Driver::TB6612, 5, 22, 23, 2, 30}, MOTOR);   // wheel_left_joint
  a[n++] = &m0;
  static bridge::DcMotor m1(1, {bridge::Driver::TB6612, 6, 24, 25, 3, 31}, MOTOR);   // wheel_right_joint
  a[n++] = &m1;
  static bridge::Mpu6050 mpu;   // or bridge::Bno055 bno; (I2C)
  imu = &mpu;
}
